import { spawnSync } from 'node:child_process';
import { randomBytes } from 'node:crypto';
import { existsSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';

/**
 * The prior-line upgrade fixture: a production app generated by the LAST
 * PUBLISHED CLI and core (0.2.0 / 0.11.0), moved onto the archives under
 * test with the command MIGRATING.md names.
 *
 *   node scripts/upgrade-smoke.mjs <new-artifacts> [old cli version] [old core version]
 *
 * Proves, without services: the unmigrated app is refused by the new core
 * with a 0.12 diagnostic naming `tulipes migrate 0.12` (the 0.11 array form
 * of tulipes.env, met before the unscoped ids) before any connection; the
 * command then leaves an app that installs, syncs, typechecks, describes
 * itself offline on plain node with every id scoped and every variable read
 * through ctx.config, and boots far enough to reach its database provider.
 *
 * The 0.10 → 0.11 → 0.12 chain is covered by packages/cli/tests/migrate.test.ts.
 */
const [artifactPath, oldCli = '0.2.0', oldCore = '0.11.0'] = process.argv.slice(2);
if (!artifactPath) throw new Error('Usage: upgrade-smoke.mjs <artifacts> [old cli version] [old core version]');
const artifacts = resolve(artifactPath);
const workspace = mkdtempSync(join(tmpdir(), 'tulipes-upgrade-'));
const scripts = import.meta.dirname;
const logs = resolve('reports', 'upgrade-smoke');
mkdirSync(logs, { recursive: true });
let step = 0;
function run(command, args, cwd, env = process.env, { expectFailure } = {}) {
  const result = spawnSync(command, args, { cwd, env, encoding: 'utf8', timeout: 180_000 });
  const file = join(logs, `${String(++step).padStart(2, '0')}-${command.split('/').at(-1)}.log`);
  const output = (result.stdout ?? '') + (result.stderr ?? '');
  writeFileSync(file, `$ ${command} ${args.join(' ')}\n\n` + output);
  const failed = result.status !== 0;
  if (failed !== Boolean(expectFailure)) throw new Error(`${command} ${args.join(' ')} ${failed ? 'failed' : 'unexpectedly succeeded'}; see ${file}\n${result.error ?? ''}\n${result.stderr ?? ''}`);
  return output;
}
const install = (cwd, env = process.env) => run('pnpm', ['install', '--no-frozen-lockfile'], cwd, env);
const readJson = file => JSON.parse(readFileSync(file, 'utf8'));
const writeJson = (file, value) => writeFileSync(file, JSON.stringify(value, null, 2) + '\n');

try {
  run(process.execPath, [join(scripts, 'artifacts.mjs'), 'verify', artifacts], workspace);
  const manifest = readJson(join(artifacts, 'manifest.json'));
  const resolutions = Object.fromEntries(manifest.packages.map(pkg => [pkg.name, 'file:' + join(artifacts, pkg.file)]));

  // 1. The old world: the last published CLI generates a production app.
  const oldRoot = join(workspace, 'old-cli');
  mkdirSync(oldRoot);
  writeJson(join(oldRoot, 'package.json'), { private: true, packageManager: 'pnpm@10.28.0', dependencies: { '@tulipes/cli': oldCli, '@tulipes/core': oldCore } });
  install(oldRoot);
  const generatedBy = readJson(join(oldRoot, 'node_modules/@tulipes/core/package.json')).version;
  const app = join(workspace, 'app');
  run(process.execPath, [join(oldRoot, 'node_modules/@tulipes/cli/dist/bin.js'), 'init', app, '--preset', 'production'], workspace);
  const pkgFile = join(app, 'package.json');
  const oldRoutes = join(app, 'modules/auth/routes/auth.routes.ts');
  if (!existsSync(oldRoutes) || !readFileSync(oldRoutes, 'utf8').includes('id: "auth:login"')) throw new Error('The old starter does not declare the 0.11 ids this fixture upgrades from');

  // 2. The new archives installed under the old app, nothing else changed.
  const before = readJson(pkgFile);
  writeJson(pkgFile, { ...before, pnpm: { ...before.pnpm, overrides: { ...before.pnpm?.overrides, ...resolutions } } });
  const env = { ...process.env, APP_ENV: 'production', LOG_FILE: 'false', LOG_CONSOLE: 'false', PORT: '0',
    MONGO_URI: 'mongodb://127.0.0.1:1/unreachable', REDIS_URL: 'redis://127.0.0.1:1',
    JWT_ACCESS_SECRET: randomBytes(32).toString('hex'), JWT_REFRESH_SECRET: randomBytes(32).toString('hex'),
    AUTH_ADMIN_EMAIL: 'upgrade@example.test', AUTH_ADMIN_PASSWORD: randomBytes(32).toString('hex') };
  install(app, env);
  const installed = readJson(join(app, 'node_modules/@tulipes/core/package.json')).version;
  const expected = manifest.packages.find(pkg => pkg.name === '@tulipes/core').version;
  if (installed !== expected) throw new Error(`the app installed core ${installed}, not the archive under test (${expected})`);
  const newBin = join(app, 'node_modules/@tulipes/cli/dist/bin.js');
  const guard = join(app, 'offline-guard.mjs');
  writeFileSync(guard, `import { Socket } from 'node:net';\nSocket.prototype.connect = function () { throw new Error('a connection was attempted'); };\n`);
  writeFileSync(join(app, 'try-boot.mjs'), `
    import { boot } from '@tulipes/core/boot';
    try { const handle = await boot({ rootDir: import.meta.dirname, mode: 'script', handleSignals: false }); await handle.shutdown(); }
    catch (error) { console.error(error.message); process.exit(3); }
  `);
  const tryBoot = () => run(process.execPath, ['--import', guard, 'try-boot.mjs'], app, env, { expectFailure: true });

  // 2a. Unmigrated: the inspection refuses the app at the first 0.12 contract
  // it meets — the 0.11 array form of tulipes.env, read with the manifests
  // before the ACL would refuse the unscoped grants — naming the command
  // that fixes it, never connecting.
  let output = run(process.execPath, ['--import', guard, newBin, 'routes'], app, env, { expectFailure: true });
  if (!/tulipes\.env is an object keyed by config name since 0\.12.*tulipes migrate 0\.12/.test(output)) throw new Error(`Unmigrated app was not told to run tulipes migrate 0.12\n${output}`);
  if (output.includes('a connection was attempted')) throw new Error('Unmigrated app attempted a connection');

  // 3. The command.
  output = run(process.execPath, [newBin, 'migrate', '0.12'], app, env);
  if (!/scoped \d+ id\(s\) "web"/.test(output)) throw new Error('migrate reported nothing\n' + output);
  const record = readJson(join(app, 'config/migration-0.12.json'));
  for (const [from, to] of [['auth:login', 'auth:web:login'], ['users:read', 'users:web:read'], ['settings:logs', 'settings:web:logs'], ['hello:reset-counts', 'hello:web:reset-counts']]) {
    if (record.ids[from] !== to) throw new Error(`migration did not record ${from} → ${to}: ${JSON.stringify(record.ids)}`);
  }
  if (record.todos.length > 0) throw new Error('migrate left TODOs on the reference app: ' + record.todos.join('; '));
  if (!readFileSync(oldRoutes, 'utf8').includes('id: "auth:web:login"')) throw new Error('migrate did not rewrite the routes');
  // The environment moved into the config: declarations keyed by name, the app config wiring the providers.
  if (record.env?.core?.MONGO_URI !== 'mongoUri' || record.env?.auth?.JWT_ACCESS_SECRET !== 'jwtAccessSecret') throw new Error(`migration did not key the variables: ${JSON.stringify(record.env)}`);
  const coreManifest = readJson(join(app, 'modules/core/package.json'));
  if (coreManifest.tulipes.env.mongoUri?.key !== 'MONGO_URI') throw new Error('migrate did not rewrite the core declaration: ' + JSON.stringify(coreManifest.tulipes.env));
  const appConfig = readFileSync(join(app, 'config/app.config.ts'), 'utf8');
  if (!appConfig.includes('mongoose: { uri: env.core.mongoUri }') || !appConfig.includes('server: { port: env.core.port }')) throw new Error('migrate did not wire the app config\n' + appConfig);

  // 3b. The MCP process (0.13): added beside app.ts; the old auth module has
  // no API tokens, so the config is the development identity and the report
  // says what to copy. The typecheck below covers both new files.
  output = run(process.execPath, [newBin, 'migrate', '0.13'], app, env);
  if (!existsSync(join(app, 'mcp.ts')) || !readFileSync(join(app, 'config/mcp.config.ts'), 'utf8').includes('developmentIdentity')) throw new Error('migrate 0.13 did not add the MCP process\n' + output);
  if (!output.includes('modules/auth/helpers/api-tokens.ts')) throw new Error('migrate 0.13 did not list the auth files to copy\n' + output);
  if (readJson(join(app, 'package.json')).scripts?.mcp !== 'node mcp.ts') throw new Error('migrate 0.13 did not add the mcp script');
  install(app, env);

  // 4. The migrated app, on plain node: syncs, typechecks, describes itself offline, boots to its provider.
  for (const script of ['sync', 'typecheck']) run('pnpm', [script], app, env);
  output = run(process.execPath, ['--import', guard, newBin, 'routes'], app, env);
  if (!output.includes('auth:web:login')) throw new Error('Migrated routes do not list the scoped ids\n' + output);
  run(process.execPath, ['--import', guard, newBin, 'spec', '--openapi', 'docs/openapi.json', '--postman', 'docs/collection.json'], app, env);
  const spec = readJson(join(app, 'docs/openapi.json'));
  const login = spec.paths['/api/v1/auth/login']?.post;
  if (login?.operationId !== 'auth:web:login' || login['x-tulipes-scope'] !== 'web' || !login['x-tulipes-roles'].includes('guest')) throw new Error('Migrated app does not describe login as auth:web:login for guest: ' + JSON.stringify(login));
  output = tryBoot();
  if (!/Boot aborted during "providers"/.test(output) || !/database connection failed/.test(output)) throw new Error('Migrated app did not reach the Mongoose provider\n' + output);

  const keyed = Object.values(record.env).reduce((n, m) => n + Object.keys(m).length, 0);
  writeJson(join(logs, 'summary.json'), { generatedBy, oldCli, upgradedTo: Object.fromEntries(manifest.packages.map(pkg => [pkg.name, pkg.version])), scoped: Object.keys(record.ids).length, keyed });
  console.log(`upgrade: production app generated by cli ${oldCli} / core ${generatedBy} was refused with the 0.12 diagnostic, then migrated with \`tulipes migrate 0.12\` and \`0.13\` (${Object.keys(record.ids).length} ids scoped, ${keyed} variables keyed), installed, typechecked, described itself offline on node and boots to its provider on ${manifest.packages.map(pkg => `${pkg.name}@${pkg.version}`).join(', ')}`);
} finally {
  rmSync(workspace, { recursive: true, force: true });
}
